insert into public.recipes (slug,name,image,time_mins,kcal,servings,description,steps,source) values ('caesar-salad','Caesar Salad','https://images.unsplash.com/photo-1550304943-4f24f54ddde9?w=600&q=80',10,350,2,'A classic: crisp romaine, parmesan, croutons and a creamy dressing.',$steps$[{"section":"Get everything ready","duration":300,"tip":"Set up every station before any heat goes under a pan. Once cooking starts, each step moves quickly.","youtubeQuery":"Caesar Salad mise en place","instructions":[{"text":"Trim the base of the 1 head romaine and separate the leaves.","parts":[{"t":"Trim the base of the ","hl":false},{"t":"1 head romaine","hl":true},{"t":" and separate the leaves.","hl":false}]},{"text":"Finely grate 40 g parmesan and split it into two piles.","parts":[{"t":"Finely grate ","hl":false},{"t":"40 g parmesan","hl":true},{"t":" and split it into two piles.","hl":false}]},{"text":"Peel 1 clove garlic and halve the lemon, picking out the seeds.","parts":[{"t":"Peel ","hl":false},{"t":"1 clove garlic","hl":true},{"t":" and halve the ","hl":false},{"t":"lemon","hl":true},{"t":", picking out the seeds.","hl":false}]},{"text":"Small bowl: measure in 2 tbsp mayonnaise. Keep the 1 cup croutons aside for the very end.","parts":[{"t":"Small bowl: measure in ","hl":false},{"t":"2 tbsp mayonnaise","hl":true},{"t":". Keep the ","hl":false},{"t":"1 cup croutons","hl":true},{"t":" aside for the very end.","hl":false}]}]},{"section":"Make the dressing","duration":180,"tip":"Grate the garlic on a Microplane so it melts into the dressing instead of leaving raw chunks.","youtubeQuery":"easy caesar dressing with mayonnaise","instructions":[{"text":"In the small bowl, add 2 tbsp mayonnaise, 1 tsp Dijon mustard and 1 tsp Worcestershire sauce.","parts":[{"t":"In the small bowl, add ","hl":false},{"t":"2 tbsp mayonnaise","hl":true},{"t":", ","hl":false},{"t":"1 tsp Dijon mustard","hl":true},{"t":" and ","hl":false},{"t":"1 tsp Worcestershire sauce","hl":true},{"t":".","hl":false}]},{"text":"Grate 1 clove garlic straight into the bowl (about ½ tsp grated).","parts":[{"t":"Grate ","hl":false},{"t":"1 clove garlic","hl":true},{"t":" straight into the bowl (about ½ tsp grated).","hl":false}]},{"text":"Squeeze in the juice of ½ lemon (about 1 tbsp). Catch the seeds with your fingers.","parts":[{"t":"Squeeze in the juice of ","hl":false},{"t":"½ lemon","hl":true},{"t":" (about ","hl":false},{"t":"1 tbsp","hl":true},{"t":"). Catch the seeds with your fingers.","hl":false}]},{"text":"Whisk for 30 seconds until smooth and pale, then stir in half the parmesan (20 g, about ¼ cup).","parts":[{"t":"Whisk for ","hl":false},{"t":"30 seconds","hl":true},{"t":" until smooth and pale, then stir in half the parmesan (","hl":false},{"t":"20 g, about ¼ cup","hl":true},{"t":").","hl":false}]},{"text":"Taste: it should be tangy and garlicky. Too thick? Whisk in 1 tsp water.","parts":[{"t":"Taste: it should be tangy and garlicky. Too thick? Whisk in ","hl":false},{"t":"1 tsp water","hl":true},{"t":".","hl":false}]}]},{"section":"Wash, dry and chop the romaine","duration":240,"tip":"Wet leaves water down the dressing and it slides off. Dry them twice if in doubt.","youtubeQuery":"how to cut romaine lettuce for salad","instructions":[{"text":"Rinse the romaine leaves under cold water, rubbing the base of each leaf where grit hides.","parts":[{"t":"Rinse the romaine leaves under cold water, rubbing the base of each leaf where grit hides.","hl":false}]},{"text":"Spin dry, or roll in a clean towel and press. The leaves must be completely dry.","parts":[{"t":"Spin dry, or roll in a clean towel and press. The leaves must be completely dry.","hl":false}]},{"text":"Stack 4 to 5 leaves and cut across into 1 inch (2.5 cm) wide ribbons. Discard the very bottom 1 inch of stem.","parts":[{"t":"Stack 4 to 5 leaves and cut across into ","hl":false},{"t":"1 inch (2.5 cm)","hl":true},{"t":" wide ribbons. Discard the very bottom 1 inch of stem.","hl":false}]},{"text":"Put all the chopped romaine (about 6 cups) in the large bowl.","parts":[{"t":"Put all the chopped romaine (about ","hl":false},{"t":"6 cups","hl":true},{"t":") in the large bowl.","hl":false}]}]},{"section":"Toss and serve","duration":120,"tip":"Croutons go on last so they stay crunchy.","youtubeQuery":"how to toss caesar salad","instructions":[{"text":"Pour about two thirds of the dressing over the romaine.","parts":[{"t":"Pour about ","hl":false},{"t":"two thirds","hl":true},{"t":" of the dressing over the romaine.","hl":false}]},{"text":"Toss with tongs for 20 to 30 seconds, lifting from the bottom, until every leaf has a light coat. Add the rest only if it looks dry.","parts":[{"t":"Toss with tongs for ","hl":false},{"t":"20 to 30 seconds","hl":true},{"t":", lifting from the bottom, until every leaf has a light coat. Add the rest only if it looks dry.","hl":false}]},{"text":"Scatter 1 cup croutons and the remaining 20 g parmesan on top.","parts":[{"t":"Scatter ","hl":false},{"t":"1 cup croutons","hl":true},{"t":" and the remaining ","hl":false},{"t":"20 g parmesan","hl":true},{"t":" on top.","hl":false}]},{"text":"Finish with 1 tsp black pepper and serve right away, split between 2 plates.","parts":[{"t":"Finish with ","hl":false},{"t":"1 tsp black pepper","hl":true},{"t":" and serve right away, split between ","hl":false},{"t":"2 plates","hl":true},{"t":".","hl":false}]}]}]$steps$::jsonb,'recipe-dataset') on conflict (slug) do update set name=excluded.name,image=excluded.image,time_mins=excluded.time_mins,kcal=excluded.kcal,servings=excluded.servings,description=excluded.description,steps=excluded.steps,source=excluded.source;
