  ((select id from public.recipes where slug = 'caesar-salad'),'parmesan','Parmesan',40,'g',false,false),
  ((select id from public.recipes where slug = 'caesar-salad'),'croutons','Croutons',1,'cup',false,false),
  ((select id from public.recipes where slug = 'caesar-salad'),'mayonnaise','Mayonnaise',2,'tbsp',false,false),
  ((select id from public.recipes where slug = 'caesar-salad'),'dijon mustard','Dijon Mustard',1,'tsp',false,false),
  ((select id from public.recipes where slug = 'caesar-salad'),'worcestershire','Worcestershire',1,'tsp',false,false),
  ((select id from public.recipes where slug = 'caesar-salad'),'garlic','Garlic',1,'clove',false,false),
  ((select id from public.recipes where slug = 'caesar-salad'),'lemon','Lemon',0.5,'unit',false,false),
  ((select id from public.recipes where slug = 'caesar-salad'),'black pepper','Black Pepper',1,'tsp',false,true);
insert into public.recipes (slug,name,image,time_mins,kcal,servings,description,steps,source) values ('aglio-olio-spaghetti','Aglio e Olio Spaghetti','https://thumb.wikimedia.org/wikipedia/commons/thumb/3/3e/Spaghetti_aglio_e_olio_KB.jpg/960px-Spaghetti_aglio_e_olio_KB.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail',12,550,2,'Garlic, olive oil, chili and pasta. Five ingredients, big flavor.',$steps$[{"section":"Get everything ready","duration":180,"tip":"Set up every station before any heat goes under a pan. Once cooking starts, each step moves quickly.","youtubeQuery":"Aglio e Olio Spaghetti mise en place","instructions":[{"text":"Peel 4 cloves garlic and slice them paper thin.","parts":[{"t":"Peel ","hl":false},{"t":"4 cloves garlic","hl":true},{"t":" and slice them paper thin.","hl":false}]},{"text":"Finely chop 1 chili (scrape out the seeds for less heat).","parts":[{"t":"Finely chop ","hl":false},{"t":"1 chili","hl":true},{"t":" (scrape out the seeds for less heat).","hl":false}]},{"text":"Measure 3 tbsp olive oil and 7 oz (200 g) spaghetti.","parts":[{"t":"Measure ","hl":false},{"t":"3 tbsp olive oil","hl":true},{"t":" and ","hl":false},{"t":"7 oz (200 g) spaghetti","hl":true},{"t":".","hl":false}]},{"text":"Finely grate 30 g parmesan and set the heatproof mug by the stove for pasta water.","parts":[{"t":"Finely grate ","hl":false},{"t":"30 g parmesan","hl":true},{"t":" and set the heatproof mug by the stove for pasta water.","hl":false}]}]},{"section":"Boil the water","duration":420,"tip":"A lid gets the water boiling noticeably faster.","youtubeQuery":"how to boil water for pasta","meanwhile":"While the water heats, put the oil, sliced garlic and chili in the cold skillet so it’s ready to go.","instructions":[{"text":"Fill the large pot with 3 quarts (3 L) water, cover and bring to a rolling boil over high heat (about 7 minutes).","parts":[{"t":"Fill the large pot with ","hl":false},{"t":"3 quarts (3 L) water","hl":true},{"t":", cover and bring to a rolling boil over high heat (about 7 minutes).","hl":false}]},{"text":"Add 1 tsp salt once it boils.","parts":[{"t":"Add ","hl":false},{"t":"1 tsp salt","hl":true},{"t":" once it boils.","hl":false}]}]},{"section":"Cook the spaghetti","duration":480,"tip":"Start the garlic (next step) when the pasta has about 4 minutes left so both finish together.","youtubeQuery":"how to cook spaghetti al dente","meanwhile":"When the pasta has about 4 minutes left, start the garlic in the skillet (step 3) so both finish together.","instructions":[{"text":"Add 7 oz (200 g) spaghetti and stir for the first 30 seconds so it doesn’t stick.","parts":[{"t":"Add ","hl":false},{"t":"7 oz (200 g) spaghetti","hl":true},{"t":" and stir for the first ","hl":false},{"t":"30 seconds","hl":true},{"t":" so it doesn’t stick.","hl":false}]},{"text":"Boil uncovered for 1 minute less than the packet says (usually 8 minutes).","parts":[{"t":"Boil uncovered for ","hl":false},{"t":"1 minute less","hl":true},{"t":" than the packet says (usually ","hl":false},{"t":"8 minutes","hl":true},{"t":").","hl":false}]},{"text":"Before draining, scoop out 1 cup (240 ml) pasta water with the mug. Then drain.","parts":[{"t":"Before draining, scoop out ","hl":false},{"t":"1 cup (240 ml) pasta water","hl":true},{"t":" with the mug. Then drain.","hl":false}]}]},{"section":"Gently cook the garlic and chili","duration":240,"tip":"Starting garlic in cold oil lets it flavour the oil slowly without burning.","youtubeQuery":"aglio e olio garlic oil","instructions":[{"text":"Put 3 tbsp olive oil, the sliced 4 cloves garlic and the chopped 1 chili in the cold skillet.","parts":[{"t":"Put ","hl":false},{"t":"3 tbsp olive oil","hl":true},{"t":", the sliced ","hl":false},{"t":"4 cloves garlic","hl":true},{"t":" and the chopped ","hl":false},{"t":"1 chili","hl":true},{"t":" in the cold skillet.","hl":false}]},{"text":"Turn the heat to medium-low. Cook 3 to 4 minutes, stirring, until the garlic is pale gold and smells sweet.","parts":[{"t":"Turn the heat to ","hl":false},{"t":"medium-low","hl":true},{"t":". Cook ","hl":false},{"t":"3 to 4 minutes","hl":true},{"t":", stirring, until the garlic is pale gold and smells sweet.","hl":false}]},{"text":"If the garlic starts to brown, pull the pan off the heat right away. Brown garlic tastes bitter.","parts":[{"t":"If the garlic starts to brown, pull the pan off the heat right away. Brown garlic tastes bitter.","hl":false}]}]},{"section":"Toss and serve","duration":120,"tip":"Constant tossing is what turns the oil and starchy water into a silky sauce.","youtubeQuery":"aglio e olio emulsify pasta water","instructions":[{"text":"Add the drained spaghetti to the skillet with ¼ cup (60 ml) of the pasta water.","parts":[{"t":"Add the drained spaghetti to the skillet with ","hl":false},{"t":"¼ cup (60 ml)","hl":true},{"t":" of the pasta water.","hl":false}]},{"text":"Toss with tongs over medium heat for 1 to 2 minutes until the liquid turns glossy and coats the strands. Add another splash of water if it looks dry.","parts":[{"t":"Toss with tongs over ","hl":false},{"t":"medium heat","hl":true},{"t":" for ","hl":false},{"t":"1 to 2 minutes","hl":true},{"t":" until the liquid turns glossy and coats the strands. Add another splash of water if it looks dry.","hl":false}]},{"text":"Turn off the heat, add 30 g (about ⅓ cup) parmesan, toss again and serve on 2 plates.","parts":[{"t":"Turn off the heat, add ","hl":false},{"t":"30 g (about ⅓ cup) parmesan","hl":true},{"t":", toss again and serve on ","hl":false},{"t":"2 plates","hl":true},{"t":".","hl":false}]}]}]$steps$::jsonb,'json-cookbook') on conflict (slug) do update set name=excluded.name,image=excluded.image,time_mins=excluded.time_mins,kcal=excluded.kcal,servings=excluded.servings,description=excluded.description,steps=excluded.steps,source=excluded.source;
insert into public.recipe_ingredients (recipe_id,canonical,display,quantity,unit,optional,staple) values
  ((select id from public.recipes where slug = 'aglio-olio-spaghetti'),'pasta','Spaghetti',200,'g',false,false),
  ((select id from public.recipes where slug = 'aglio-olio-spaghetti'),'garlic','Garlic',4,'clove',false,false),
  ((select id from public.recipes where slug = 'aglio-olio-spaghetti'),'olive oil','Olive Oil',3,'tbsp',false,true),
  ((select id from public.recipes where slug = 'aglio-olio-spaghetti'),'chili','Chili',1,'unit',false,false),
  ((select id from public.recipes where slug = 'aglio-olio-spaghetti'),'parmesan','Parmesan',30,'g',false,false),
  ((select id from public.recipes where slug = 'aglio-olio-spaghetti'),'salt','Salt',1,'tsp',false,true);
insert into public.recipes (slug,name,image,time_mins,kcal,servings,description,steps,source) values ('caesar-wrap','Caesar Wrap','https://thumb.wikimedia.org/wikipedia/commons/thumb/0/08/Crispy_Chick%27n_Caesar_Wrap.jpg/960px-Crispy_Chick%27n_Caesar_Wrap.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail',10,380,2,'Caesar salad rolled into a soft tortilla with grilled chicken.',$steps$[{"section":"Get everything ready","duration":300,"tip":"Set up every station before any heat goes under a pan. Once cooking starts, each step moves quickly.","youtubeQuery":"Caesar Wrap mise en place","instructions":[{"text":"Pat the 7 oz (200 g) chicken breast dry and season both sides with a pinch of salt and pepper.","parts":[{"t":"Pat the ","hl":false},{"t":"7 oz (200 g) chicken breast","hl":true},{"t":" dry and season both sides with a pinch of salt and pepper.","hl":false}]},{"text":"Wash, dry and chop ½ head romaine into ½ inch (1 cm) ribbons.","parts":[{"t":"Wash, dry and chop ","hl":false},{"t":"½ head romaine","hl":true},{"t":" into ½ inch (1 cm) ribbons.","hl":false}]},{"text":"Finely grate 20 g parmesan and 1 clove garlic.","parts":[{"t":"Finely grate ","hl":false},{"t":"20 g parmesan","hl":true},{"t":" and ","hl":false},{"t":"1 clove garlic","hl":true},{"t":".","hl":false}]},{"text":"Medium bowl: measure in 2 tbsp mayonnaise, and set out the 2 tortillas.","parts":[{"t":"Medium bowl: measure in ","hl":false},{"t":"2 tbsp mayonnaise","hl":true},{"t":", and set out the ","hl":false},{"t":"2 tortillas","hl":true},{"t":".","hl":false}]}]},{"section":"Cook the chicken","duration":720,"tip":"If the breast is thicker than 1 inch, slice it in half horizontally first so it cooks evenly.","youtubeQuery":"how to pan fry chicken breast juicy","meanwhile":"While the chicken rests, dress the lettuce (step 2) so the wraps come together in one go.","instructions":[{"text":"Heat 1 tsp oil in the skillet over medium-high heat until it shimmers (about 1 minute).","parts":[{"t":"Heat ","hl":false},{"t":"1 tsp oil","hl":true},{"t":" in the skillet over ","hl":false},{"t":"medium-high","hl":true},{"t":" heat until it shimmers (about 1 minute).","hl":false}]},{"text":"Lay in the 7 oz (200 g) chicken breast and cook 5 to 6 minutes without moving it, until golden underneath.","parts":[{"t":"Lay in the ","hl":false},{"t":"7 oz (200 g) chicken breast","hl":true},{"t":" and cook ","hl":false},{"t":"5 to 6 minutes","hl":true},{"t":" without moving it, until golden underneath.","hl":false}]},{"text":"Flip and cook 5 to 6 minutes more, until the thickest part reads 165°F (74°C) or the juices run clear.","parts":[{"t":"Flip and cook ","hl":false},{"t":"5 to 6 minutes","hl":true},{"t":" more, until the thickest part reads ","hl":false},{"t":"165°F (74°C)","hl":true},{"t":" or the juices run clear.","hl":false}]},{"text":"Move to the board and rest 5 minutes, then slice into thin strips.","parts":[{"t":"Move to the board and rest ","hl":false},{"t":"5 minutes","hl":true},{"t":", then slice into thin strips.","hl":false}]}]},{"section":"Dress the lettuce","duration":120,"tip":"Dress the lettuce right before wrapping so it stays crisp.","youtubeQuery":"chicken caesar wrap","instructions":[{"text":"In the medium bowl, mix 2 tbsp mayonnaise, the grated 1 clove garlic and half the parmesan (10 g).","parts":[{"t":"In the medium bowl, mix ","hl":false},{"t":"2 tbsp mayonnaise","hl":true},{"t":", the grated ","hl":false},{"t":"1 clove garlic","hl":true},{"t":" and half the parmesan (","hl":false},{"t":"10 g","hl":true},{"t":").","hl":false}]},{"text":"Add the chopped ½ head romaine and the remaining 10 g parmesan. Toss until coated.","parts":[{"t":"Add the chopped ","hl":false},{"t":"½ head romaine","hl":true},{"t":" and the remaining ","hl":false},{"t":"10 g parmesan","hl":true},{"t":". Toss until coated.","hl":false}]}]},{"section":"Warm, fill and roll","duration":180,"tip":"Keep the filling in a tight line and leave a 2 inch border at the sides so the wrap closes.","youtubeQuery":"how to roll a wrap burrito fold","instructions":[{"text":"Wipe the skillet and warm each of the 2 tortillas over medium heat for 20 seconds per side so they bend without cracking.","parts":[{"t":"Wipe the skillet and warm each of the ","hl":false},{"t":"2 tortillas","hl":true},{"t":" over ","hl":false},{"t":"medium","hl":true},{"t":" heat for ","hl":false},{"t":"20 seconds per side","hl":true},{"t":" so they bend without cracking.","hl":false}]},{"text":"Lay half the lettuce and half the chicken in a line across the lower third of each tortilla.","parts":[{"t":"Lay half the lettuce and half the chicken in a line across the lower third of each tortilla.","hl":false}]},{"text":"Fold in the sides, then roll up tightly from the bottom. Cut each wrap in half on the diagonal.","parts":[{"t":"Fold in the sides, then roll up tightly from the bottom. Cut each wrap in half on the diagonal.","hl":false}]}]}]$steps$::jsonb,'recipe-dataset') on conflict (slug) do update set name=excluded.name,image=excluded.image,time_mins=excluded.time_mins,kcal=excluded.kcal,servings=excluded.servings,description=excluded.description,steps=excluded.steps,source=excluded.source;
