  ((select id from public.recipes where slug = 'caesar-wrap'),'tortilla','Tortillas',2,'unit',false,false),
  ((select id from public.recipes where slug = 'caesar-wrap'),'chicken','Chicken Breast',200,'g',false,false),
  ((select id from public.recipes where slug = 'caesar-wrap'),'lettuce','Romaine Lettuce',0.5,'head',false,false),
  ((select id from public.recipes where slug = 'caesar-wrap'),'parmesan','Parmesan',20,'g',false,false),
