  ((select id from public.recipes where slug = 'caesar-wrap'),'garlic','Garlic',1,'clove',false,false);
insert into public.recipes (slug,name,image,time_mins,kcal,servings,description,steps,source) values ('bacon-ham-sandwich','Bacon Ham Sandwich','https://images.unsplash.com/photo-1528735602780-2552fd46c7af?w=600&q=80',7,600,1,'Toasted bread, crispy bacon, cheese and a fried egg.',$steps$[{"section":"Get everything ready","duration":120,"tip":"Set up every station before any heat goes under a pan. Once cooking starts, each step moves quickly.","youtubeQuery":"Bacon Ham Sandwich mise en place","instructions":[{"text":"Set the skillet on the stove and line a plate with paper towels.","parts":[{"t":"Set the skillet on the stove and line a plate with paper towels.","hl":false}]},{"text":"Leave 1 tbsp butter out to soften, and slice or grate 30 g cheese.","parts":[{"t":"Leave ","hl":false},{"t":"1 tbsp butter","hl":true},{"t":" out to soften, and slice or grate ","hl":false},{"t":"30 g cheese","hl":true},{"t":".","hl":false}]},{"text":"Set out 2 slices bread, 3 slices bacon and 1 egg.","parts":[{"t":"Set out ","hl":false},{"t":"2 slices bread","hl":true},{"t":", ","hl":false},{"t":"3 slices bacon","hl":true},{"t":" and ","hl":false},{"t":"1 egg","hl":true},{"t":".","hl":false}]}]},{"section":"Cook the bacon","duration":420,"tip":"Starting bacon in a cold pan renders the fat slowly, so it crisps evenly instead of burning.","youtubeQuery":"how to cook crispy bacon in a pan","instructions":[{"text":"Lay 3 slices bacon in the cold skillet, side by side.","parts":[{"t":"Lay ","hl":false},{"t":"3 slices bacon","hl":true},{"t":" in the cold skillet, side by side.","hl":false}]},{"text":"Turn the heat to medium. Cook 6 to 8 minutes, turning every 2 minutes, until crisp and deep golden.","parts":[{"t":"Turn the heat to ","hl":false},{"t":"medium","hl":true},{"t":". Cook ","hl":false},{"t":"6 to 8 minutes","hl":true},{"t":", turning every 2 minutes, until crisp and deep golden.","hl":false}]},{"text":"Move the bacon to paper towels. Leave about 1 tsp fat in the pan and pour off the rest.","parts":[{"t":"Move the bacon to paper towels. Leave about ","hl":false},{"t":"1 tsp fat","hl":true},{"t":" in the pan and pour off the rest.","hl":false}]}]},{"section":"Fry the egg","duration":180,"tip":"Low heat keeps the edges from going brown and rubbery.","youtubeQuery":"how to fry an egg perfectly","instructions":[{"text":"Keep the pan on medium-low. Crack in 1 egg.","parts":[{"t":"Keep the pan on ","hl":false},{"t":"medium-low","hl":true},{"t":". Crack in ","hl":false},{"t":"1 egg","hl":true},{"t":".","hl":false}]},{"text":"Cook 2 to 3 minutes until the white is fully set and the yolk is still soft. For a firm yolk, flip and cook 1 more minute.","parts":[{"t":"Cook ","hl":false},{"t":"2 to 3 minutes","hl":true},{"t":" until the white is fully set and the yolk is still soft. For a firm yolk, flip and cook ","hl":false},{"t":"1 more minute","hl":true},{"t":".","hl":false}]},{"text":"Season with a small pinch of salt and pepper and slide it onto a plate.","parts":[{"t":"Season with a small pinch of salt and pepper and slide it onto a plate.","hl":false}]}]},{"section":"Toast and assemble","duration":240,"tip":"Cover the pan for the last minute to melt the cheese faster.","youtubeQuery":"bacon egg and cheese sandwich","instructions":[{"text":"Spread 1 tbsp butter over one side of both 2 slices bread.","parts":[{"t":"Spread ","hl":false},{"t":"1 tbsp butter","hl":true},{"t":" over one side of both ","hl":false},{"t":"2 slices bread","hl":true},{"t":".","hl":false}]},{"text":"Put the bread butter-side down in the pan over medium heat. Top one slice with the 30 g cheese.","parts":[{"t":"Put the bread butter-side down in the pan over ","hl":false},{"t":"medium","hl":true},{"t":" heat. Top one slice with the ","hl":false},{"t":"30 g cheese","hl":true},{"t":".","hl":false}]},{"text":"Toast 2 to 3 minutes until golden underneath and the cheese starts to melt.","parts":[{"t":"Toast ","hl":false},{"t":"2 to 3 minutes","hl":true},{"t":" until golden underneath and the cheese starts to melt.","hl":false}]},{"text":"Layer the bacon and egg on the cheese, close with the other slice (butter-side out), press lightly and cut in half.","parts":[{"t":"Layer the bacon and egg on the cheese, close with the other slice (butter-side out), press lightly and cut in half.","hl":false}]}]}]$steps$::jsonb,'json-cookbook') on conflict (slug) do update set name=excluded.name,image=excluded.image,time_mins=excluded.time_mins,kcal=excluded.kcal,servings=excluded.servings,description=excluded.description,steps=excluded.steps,source=excluded.source;
insert into public.recipe_ingredients (recipe_id,canonical,display,quantity,unit,optional,staple) values
  ((select id from public.recipes where slug = 'bacon-ham-sandwich'),'bread','Bread',2,'slice',false,false),
  ((select id from public.recipes where slug = 'bacon-ham-sandwich'),'bacon','Bacon',3,'slice',false,false),
  ((select id from public.recipes where slug = 'bacon-ham-sandwich'),'cheese','Cheese',30,'g',false,false),
  ((select id from public.recipes where slug = 'bacon-ham-sandwich'),'egg','Egg',1,'unit',false,false),
  ((select id from public.recipes where slug = 'bacon-ham-sandwich'),'butter','Butter',1,'tbsp',false,false);
insert into public.recipes (slug,name,image,time_mins,kcal,servings,description,steps,source) values ('guacamole','Guacamole','https://thumb.wikimedia.org/wikipedia/commons/thumb/c/c7/Doritos_and_Guacamole_in_a_wooden_bowl.JPG/960px-Doritos_and_Guacamole_in_a_wooden_bowl.JPG?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail',7,300,3,'Ripe avocado mashed with lime, onion, cilantro and chili.',$steps$[{"section":"Get everything ready","duration":120,"tip":"Set up every station before any heat goes under a pan. Once cooking starts, each step moves quickly.","youtubeQuery":"Guacamole mise en place","instructions":[{"text":"Set out the bowl, a fork, the board and a sharp knife.","parts":[{"t":"Set out the bowl, a fork, the board and a sharp knife.","hl":false}]},{"text":"Roll the 1 lime firmly on the counter, then halve it.","parts":[{"t":"Roll the ","hl":false},{"t":"1 lime","hl":true},{"t":" firmly on the counter, then halve it.","hl":false}]},{"text":"Check the 2 avocados: they should give slightly when pressed.","parts":[{"t":"Check the ","hl":false},{"t":"2 avocados","hl":true},{"t":": they should give slightly when pressed.","hl":false}]}]},{"section":"Chop the aromatics","duration":180,"tip":"Letting the onion sit in lime and salt takes away its harsh raw bite.","youtubeQuery":"how to finely dice onion","instructions":[{"text":"Finely dice ½ onion into pieces about ⅛ inch (3 mm). You want about ¼ cup.","parts":[{"t":"Finely dice ","hl":false},{"t":"½ onion","hl":true},{"t":" into pieces about ","hl":false},{"t":"⅛ inch (3 mm)","hl":true},{"t":". You want about ","hl":false},{"t":"¼ cup","hl":true},{"t":".","hl":false}]},{"text":"Cut 1 chili in half lengthways, scrape out the seeds and white ribs, then mince very finely.","parts":[{"t":"Cut ","hl":false},{"t":"1 chili","hl":true},{"t":" in half lengthways, scrape out the seeds and white ribs, then mince very finely.","hl":false}]},{"text":"Chop 1 bunch cilantro leaves and tender stems. Measure about ¼ cup for the guacamole and keep the rest for garnish.","parts":[{"t":"Chop ","hl":false},{"t":"1 bunch cilantro","hl":true},{"t":" leaves and tender stems. Measure about ","hl":false},{"t":"¼ cup","hl":true},{"t":" for the guacamole and keep the rest for garnish.","hl":false}]},{"text":"Put the onion and chili in the bowl with ½ tsp salt and the juice of ½ lime. Leave 2 minutes to soften.","parts":[{"t":"Put the onion and chili in the bowl with ","hl":false},{"t":"½ tsp salt","hl":true},{"t":" and the juice of ","hl":false},{"t":"½ lime","hl":true},{"t":". Leave ","hl":false},{"t":"2 minutes","hl":true},{"t":" to soften.","hl":false}]}]},{"section":"Mash the avocado","duration":180,"tip":"Mashing on top of the lime juice coats the avocado straight away and keeps it green.","youtubeQuery":"how to cut and pit an avocado","instructions":[{"text":"Cut 2 avocados in half around the pit, twist apart and remove the pit with a spoon.","parts":[{"t":"Cut ","hl":false},{"t":"2 avocados","hl":true},{"t":" in half around the pit, twist apart and remove the pit with a spoon.","hl":false}]},{"text":"Scoop the flesh into the bowl with the onion mixture.","parts":[{"t":"Scoop the flesh into the bowl with the onion mixture.","hl":false}]},{"text":"Mash with the fork for 30 to 45 seconds, leaving some small chunks for texture.","parts":[{"t":"Mash with the fork for ","hl":false},{"t":"30 to 45 seconds","hl":true},{"t":", leaving some small chunks for texture.","hl":false}]}]},{"section":"Season and serve","duration":60,"tip":"Guacamole usually needs more salt and lime than you expect. Taste on a chip, not a spoon.","youtubeQuery":"how to season guacamole","instructions":[{"text":"Fold in the chopped cilantro.","parts":[{"t":"Fold in the chopped cilantro.","hl":false}]},{"text":"Taste, then add up to ½ tsp more salt and the juice of the other ½ lime if it needs brightness.","parts":[{"t":"Taste, then add up to ","hl":false},{"t":"½ tsp more salt","hl":true},{"t":" and the juice of the other ","hl":false},{"t":"½ lime","hl":true},{"t":" if it needs brightness.","hl":false}]},{"text":"Serve right away for 3 people, or press plastic wrap directly onto the surface and chill up to 2 hours.","parts":[{"t":"Serve right away for ","hl":false},{"t":"3 people","hl":true},{"t":", or press plastic wrap directly onto the surface and chill up to ","hl":false},{"t":"2 hours","hl":true},{"t":".","hl":false}]}]}]$steps$::jsonb,'recipe-dataset') on conflict (slug) do update set name=excluded.name,image=excluded.image,time_mins=excluded.time_mins,kcal=excluded.kcal,servings=excluded.servings,description=excluded.description,steps=excluded.steps,source=excluded.source;
