  ((select id from public.recipes where slug = 'guacamole'),'avocado','Avocado',2,'unit',false,false),
  ((select id from public.recipes where slug = 'guacamole'),'lime','Lime',1,'unit',false,false),
  ((select id from public.recipes where slug = 'guacamole'),'onion','Onion',0.5,'unit',false,false),
  ((select id from public.recipes where slug = 'guacamole'),'cilantro','Cilantro',1,'bunch',false,false),
  ((select id from public.recipes where slug = 'guacamole'),'chili','Chili',1,'unit',false,false),
  ((select id from public.recipes where slug = 'guacamole'),'salt','Salt',1,'tsp',false,true);
insert into public.recipes (slug,name,image,time_mins,kcal,servings,description,steps,source) values ('chicken-nuggets','Chicken Nuggets','https://thumb.wikimedia.org/wikipedia/commons/thumb/6/68/Impossible_chicken_nuggets_1.jpg/960px-Impossible_chicken_nuggets_1.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail',20,420,2,'Crispy breaded chicken bites, oven-baked or air-fried.',$steps$[{"section":"Get everything ready","duration":300,"tip":"Set up every station before any heat goes under a pan. Once cooking starts, each step moves quickly.","youtubeQuery":"Chicken Nuggets mise en place","instructions":[{"text":"Heat the oven to 425°F (220°C) with a rack in the middle.","parts":[{"t":"Heat the oven to ","hl":false},{"t":"425°F (220°C)","hl":true},{"t":" with a rack in the middle.","hl":false}]},{"text":"Line the baking sheet with parchment.","parts":[{"t":"Line the baking sheet with parchment.","hl":false}]},{"text":"Pat the chicken breast dry and cut it into 1½ inch (4 cm) chunks (about 20 pieces).","parts":[{"t":"Pat the ","hl":false},{"t":"chicken breast","hl":true},{"t":" dry and cut it into 1½ inch (4 cm) chunks (about 20 pieces).","hl":false}]},{"text":"Bowl 1 (dry station): mix 100 g flour with 1 tsp salt and 1 tsp pepper.","parts":[{"t":"Bowl 1 (dry station): mix ","hl":false},{"t":"100 g flour","hl":true},{"t":" with ","hl":false},{"t":"1 tsp salt","hl":true},{"t":" and ","hl":false},{"t":"1 tsp pepper","hl":true},{"t":".","hl":false}]},{"text":"Bowl 2: beat 1 egg with 1 tbsp water until smooth.","parts":[{"t":"Bowl 2: beat ","hl":false},{"t":"1 egg","hl":true},{"t":" with ","hl":false},{"t":"1 tbsp water","hl":true},{"t":" until smooth.","hl":false}]},{"text":"Bowl 3: blitz or grate 2 slices bread into fine crumbs.","parts":[{"t":"Bowl 3: blitz or grate ","hl":false},{"t":"2 slices bread","hl":true},{"t":" into fine crumbs.","hl":false}]}]},{"section":"Coat the chicken","duration":360,"tip":"Use one hand for the dry bowls and the other for the egg so your fingers don’t clump with breading.","youtubeQuery":"how to bread chicken flour egg breadcrumbs","instructions":[{"text":"Toss the chicken chunks in the flour bowl (100 g flour with 1 tsp salt and 1 tsp pepper) and shake off the excess.","parts":[{"t":"Toss the chicken chunks in the flour bowl (","hl":false},{"t":"100 g flour","hl":true},{"t":" with ","hl":false},{"t":"1 tsp salt","hl":true},{"t":" and ","hl":false},{"t":"1 tsp pepper","hl":true},{"t":") and shake off the excess.","hl":false}]},{"text":"Dip each piece in the beaten 1 egg, letting the extra drip back into the bowl.","parts":[{"t":"Dip each piece in the beaten ","hl":false},{"t":"1 egg","hl":true},{"t":", letting the extra drip back into the bowl.","hl":false}]},{"text":"Roll in the breadcrumbs from 2 slices bread and press so they stick.","parts":[{"t":"Roll in the breadcrumbs from ","hl":false},{"t":"2 slices bread","hl":true},{"t":" and press so they stick.","hl":false}]},{"text":"Lay the pieces on the sheet with 1 inch (2.5 cm) between them. Spray or drizzle lightly with oil if using.","parts":[{"t":"Lay the pieces on the sheet with ","hl":false},{"t":"1 inch (2.5 cm)","hl":true},{"t":" between them. Spray or drizzle lightly with oil if using.","hl":false}]}]},{"section":"Bake","duration":960,"tip":"Cut one open if you have no thermometer. It should be white all the way through with clear juices.","youtubeQuery":"baked chicken nuggets crispy","meanwhile":"While they bake, stir together a dipping sauce and set the table.","instructions":[{"text":"Bake 8 minutes, then flip each nugget with tongs.","parts":[{"t":"Bake ","hl":false},{"t":"8 minutes","hl":true},{"t":", then flip each nugget with tongs.","hl":false}]},{"text":"Bake 7 to 9 minutes more, until golden and the centre of a large piece reads 165°F (74°C).","parts":[{"t":"Bake ","hl":false},{"t":"7 to 9 minutes","hl":true},{"t":" more, until golden and the centre of a large piece reads ","hl":false},{"t":"165°F (74°C)","hl":true},{"t":".","hl":false}]},{"text":"Rest 2 minutes on the sheet before serving to 2 people.","parts":[{"t":"Rest ","hl":false},{"t":"2 minutes","hl":true},{"t":" on the sheet before serving to ","hl":false},{"t":"2 people","hl":true},{"t":".","hl":false}]}]}]$steps$::jsonb,'recipe-dataset') on conflict (slug) do update set name=excluded.name,image=excluded.image,time_mins=excluded.time_mins,kcal=excluded.kcal,servings=excluded.servings,description=excluded.description,steps=excluded.steps,source=excluded.source;
insert into public.recipe_ingredients (recipe_id,canonical,display,quantity,unit,optional,staple) values
  ((select id from public.recipes where slug = 'chicken-nuggets'),'chicken','Chicken Breast',300,'g',false,false),
  ((select id from public.recipes where slug = 'chicken-nuggets'),'flour','Flour',100,'g',false,true),
  ((select id from public.recipes where slug = 'chicken-nuggets'),'egg','Egg',1,'unit',false,false),
  ((select id from public.recipes where slug = 'chicken-nuggets'),'bread','Bread',2,'slice',false,false),
  ((select id from public.recipes where slug = 'chicken-nuggets'),'salt','Salt',1,'tsp',false,true),
  ((select id from public.recipes where slug = 'chicken-nuggets'),'black pepper','Black Pepper',1,'tsp',false,true);
insert into public.recipes (slug,name,image,time_mins,kcal,servings,description,steps,source) values ('chicken-strips','Chicken Strips','https://upload.wikimedia.org/wikipedia/commons/2/21/Crispy_Chicken_Strips_-_FotoosVanRobin.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail_unscaled',15,500,2,'Golden chicken tenders with a seasoned crumb.',$steps$[{"section":"Get everything ready","duration":300,"tip":"Set up every station before any heat goes under a pan. Once cooking starts, each step moves quickly.","youtubeQuery":"Chicken Strips mise en place","instructions":[{"text":"Bowl 1 (dry station): mix 80 g flour, 1 tsp paprika and ½ tsp salt.","parts":[{"t":"Bowl 1 (dry station): mix ","hl":false},{"t":"80 g flour","hl":true},{"t":", ","hl":false},{"t":"1 tsp paprika","hl":true},{"t":" and ","hl":false},{"t":"½ tsp salt","hl":true},{"t":".","hl":false}]},{"text":"Bowl 2: beat 1 egg until no streaks of white remain.","parts":[{"t":"Bowl 2: beat ","hl":false},{"t":"1 egg","hl":true},{"t":" until no streaks of white remain.","hl":false}]},{"text":"Pat the chicken breast dry and cut it lengthways into strips ½ inch (1 cm) thick.","parts":[{"t":"Pat the ","hl":false},{"t":"chicken breast","hl":true},{"t":" dry and cut it lengthways into strips ½ inch (1 cm) thick.","hl":false}]},{"text":"Line a plate with paper towels and measure 2 tbsp oil.","parts":[{"t":"Line a plate with paper towels and measure ","hl":false},{"t":"2 tbsp oil","hl":true},{"t":".","hl":false}]}]},{"section":"Coat the strips","duration":240,"tip":"The double dip (flour, egg, flour) gives a craggy coating that fries up extra crisp.","youtubeQuery":"double dredge chicken tenders","instructions":[{"text":"Dredge each strip in the flour mix (80 g flour, 1 tsp paprika, ½ tsp salt) and shake off the excess.","parts":[{"t":"Dredge each strip in the flour mix (","hl":false},{"t":"80 g flour","hl":true},{"t":", ","hl":false},{"t":"1 tsp paprika","hl":true},{"t":", ","hl":false},{"t":"½ tsp salt","hl":true},{"t":") and shake off the excess.","hl":false}]},{"text":"Dip in the beaten 1 egg, then back into the flour for a second, thicker coat.","parts":[{"t":"Dip in the beaten ","hl":false},{"t":"1 egg","hl":true},{"t":", then back into the flour for a second, thicker coat.","hl":false}]},{"text":"Set the strips on a plate in a single layer.","parts":[{"t":"Set the strips on a plate in a single layer.","hl":false}]}]},{"section":"Pan-fry","duration":480,"tip":"Crowding the pan drops the heat and makes the coating soggy. Cook in two batches.","youtubeQuery":"how to pan fry chicken tenders","instructions":[{"text":"Heat 2 tbsp oil in the skillet over medium-high until it shimmers (a pinch of flour should sizzle).","parts":[{"t":"Heat ","hl":false},{"t":"2 tbsp oil","hl":true},{"t":" in the skillet over ","hl":false},{"t":"medium-high","hl":true},{"t":" until it shimmers (a pinch of flour should sizzle).","hl":false}]},{"text":"Add half the strips with space between them. Cook 3 to 4 minutes until deep golden underneath.","parts":[{"t":"Add half the strips with space between them. Cook ","hl":false},{"t":"3 to 4 minutes","hl":true},{"t":" until deep golden underneath.","hl":false}]},{"text":"Flip and cook 3 minutes more, until the thickest strip reads 165°F (74°C).","parts":[{"t":"Flip and cook ","hl":false},{"t":"3 minutes","hl":true},{"t":" more, until the thickest strip reads ","hl":false},{"t":"165°F (74°C)","hl":true},{"t":".","hl":false}]},{"text":"Drain on the paper towels and repeat with the rest, adding a little more oil if the pan looks dry.","parts":[{"t":"Drain on the paper towels and repeat with the rest, adding a little more oil if the pan looks dry.","hl":false}]}]},{"section":"Rest and serve","duration":120,"tip":"Salt right out of the pan so it sticks to the hot coating.","youtubeQuery":"chicken strips dipping sauce","instructions":[{"text":"Rest the strips 2 minutes so the coating sets.","parts":[{"t":"Rest the strips ","hl":false},{"t":"2 minutes","hl":true},{"t":" so the coating sets.","hl":false}]},{"text":"Sprinkle with a pinch of salt while hot and serve to 2 people.","parts":[{"t":"Sprinkle with a pinch of salt while hot and serve to ","hl":false},{"t":"2 people","hl":true},{"t":".","hl":false}]}]}]$steps$::jsonb,'recipe-dataset') on conflict (slug) do update set name=excluded.name,image=excluded.image,time_mins=excluded.time_mins,kcal=excluded.kcal,servings=excluded.servings,description=excluded.description,steps=excluded.steps,source=excluded.source;
insert into public.recipe_ingredients (recipe_id,canonical,display,quantity,unit,optional,staple) values
  ((select id from public.recipes where slug = 'chicken-strips'),'chicken','Chicken Breast',350,'g',false,false),
  ((select id from public.recipes where slug = 'chicken-strips'),'flour','Flour',80,'g',false,true),
  ((select id from public.recipes where slug = 'chicken-strips'),'egg','Egg',1,'unit',false,false),
  ((select id from public.recipes where slug = 'chicken-strips'),'paprika','Paprika',1,'tsp',false,true),
  ((select id from public.recipes where slug = 'chicken-strips'),'oil','Oil',2,'tbsp',false,true);
insert into public.recipes (slug,name,image,time_mins,kcal,servings,description,steps,source) values ('chicken-fries','Chicken Fries','https://thumb.wikimedia.org/wikipedia/commons/thumb/0/00/Burger_King_Chicken_Fries_%2815423233325%29.jpg/960px-Burger_King_Chicken_Fries_%2815423233325%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail',18,450,2,'Chicken fries with a side of crispy potato fries.',$steps$[{"section":"Get everything ready","duration":420,"tip":"Set up every station before any heat goes under a pan. Once cooking starts, each step moves quickly.","youtubeQuery":"Chicken Fries mise en place","instructions":[{"text":"Heat the oven to 425°F (220°C).","parts":[{"t":"Heat the oven to ","hl":false},{"t":"425°F (220°C)","hl":true},{"t":".","hl":false}]},{"text":"Scrub 3 potatoes, cut them into ⅓ inch (8 mm) fries, then rinse and dry them really well.","parts":[{"t":"Scrub ","hl":false},{"t":"3 potatoes","hl":true},{"t":", cut them into ⅓ inch (8 mm) fries, then rinse and dry them really well.","hl":false}]},{"text":"Cut the 9 oz (250 g) chicken breast into fry-shaped sticks ½ inch (1 cm) thick.","parts":[{"t":"Cut the ","hl":false},{"t":"9 oz (250 g) chicken breast","hl":true},{"t":" into fry-shaped sticks ½ inch (1 cm) thick.","hl":false}]},{"text":"Shallow bowl (dry station): mix 60 g flour with ½ tsp salt.","parts":[{"t":"Shallow bowl (dry station): mix ","hl":false},{"t":"60 g flour","hl":true},{"t":" with ","hl":false},{"t":"½ tsp salt","hl":true},{"t":".","hl":false}]},{"text":"Line the baking sheet with parchment and a plate with paper towels.","parts":[{"t":"Line the baking sheet with parchment and a plate with paper towels.","hl":false}]}]},{"section":"Roast the potato fries","duration":1500,"tip":"Dry the cut potatoes really well. Surface water steams them instead of crisping.","youtubeQuery":"crispy oven baked fries","meanwhile":"While the fries roast, set out the flour, egg and crumb bowls and coat the chicken for step 2.","instructions":[{"text":"In the large bowl, toss the fries cut from 3 potatoes with 1½ tbsp oil and ½ tsp salt.","parts":[{"t":"In the large bowl, toss the fries cut from ","hl":false},{"t":"3 potatoes","hl":true},{"t":" with ","hl":false},{"t":"1½ tbsp oil","hl":true},{"t":" and ","hl":false},{"t":"½ tsp salt","hl":true},{"t":".","hl":false}]},{"text":"Spread on the sheet in a single layer, not touching. Roast 12 minutes, flip, then roast 10 to 13 minutes more until golden and crisp.","parts":[{"t":"Spread on the sheet in a single layer, not touching. Roast ","hl":false},{"t":"12 minutes","hl":true},{"t":", flip, then roast ","hl":false},{"t":"10 to 13 minutes","hl":true},{"t":" more until golden and crisp.","hl":false}]}]},{"section":"Coat and fry the chicken","duration":480,"tip":"Time the chicken to start when the potatoes are flipped, so everything is hot at the same time.","youtubeQuery":"chicken fries recipe","instructions":[{"text":"While the potatoes roast, toss the 9 oz (250 g) chicken sticks in the flour (60 g with ½ tsp salt) until coated.","parts":[{"t":"While the potatoes roast, toss the ","hl":false},{"t":"9 oz (250 g) chicken","hl":true},{"t":" sticks in the flour (","hl":false},{"t":"60 g","hl":true},{"t":" with ","hl":false},{"t":"½ tsp salt","hl":true},{"t":") until coated.","hl":false}]},{"text":"Heat 1½ tbsp oil in the skillet over medium-high until it shimmers.","parts":[{"t":"Heat ","hl":false},{"t":"1½ tbsp oil","hl":true},{"t":" in the skillet over ","hl":false},{"t":"medium-high","hl":true},{"t":" until it shimmers.","hl":false}]},{"text":"Fry the chicken 2 to 3 minutes per side until golden and cooked through (165°F / 74°C). Drain on paper towels.","parts":[{"t":"Fry the chicken ","hl":false},{"t":"2 to 3 minutes per side","hl":true},{"t":" until golden and cooked through (","hl":false},{"t":"165°F / 74°C","hl":true},{"t":"). Drain on paper towels.","hl":false}]}]},{"section":"Serve","duration":60,"tip":"Serve straight away. Both lose their crunch as they cool.","youtubeQuery":"chicken fries dipping sauce","instructions":[{"text":"Pile the potato fries and chicken fries together on 2 plates.","parts":[{"t":"Pile the potato fries and chicken fries together on ","hl":false},{"t":"2 plates","hl":true},{"t":".","hl":false}]},{"text":"Season with a final pinch of salt while hot.","parts":[{"t":"Season with a final pinch of salt while hot.","hl":false}]}]}]$steps$::jsonb,'json-cookbook') on conflict (slug) do update set name=excluded.name,image=excluded.image,time_mins=excluded.time_mins,kcal=excluded.kcal,servings=excluded.servings,description=excluded.description,steps=excluded.steps,source=excluded.source;
insert into public.recipe_ingredients (recipe_id,canonical,display,quantity,unit,optional,staple) values
  ((select id from public.recipes where slug = 'chicken-fries'),'chicken','Chicken Breast',250,'g',false,false),
  ((select id from public.recipes where slug = 'chicken-fries'),'potato','Potato',3,'unit',false,false),
  ((select id from public.recipes where slug = 'chicken-fries'),'flour','Flour',60,'g',false,true),
  ((select id from public.recipes where slug = 'chicken-fries'),'oil','Oil',3,'tbsp',false,true),
  ((select id from public.recipes where slug = 'chicken-fries'),'salt','Salt',1,'tsp',false,true);
insert into public.recipes (slug,name,image,time_mins,kcal,servings,description,steps,source) values ('bundt-cake','Bundt Cake','https://thumb.wikimedia.org/wikipedia/commons/thumb/e/eb/Bundt_Cake_with_Grapes_003.jpg/960px-Bundt_Cake_with_Grapes_003.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail',60,350,8,'A tender ring cake with a golden buttery crumb.',$steps$[{"section":"Get everything ready","duration":600,"tip":"Set up every station before any heat goes under a pan. Once cooking starts, each step moves quickly.","youtubeQuery":"Bundt Cake mise en place","instructions":[{"text":"Heat the oven to 350°F (175°C) with a rack in the lower middle.","parts":[{"t":"Heat the oven to ","hl":false},{"t":"350°F (175°C)","hl":true},{"t":" with a rack in the lower middle.","hl":false}]},{"text":"Leave 200 g butter out to soften (about 1 hour ahead).","parts":[{"t":"Leave ","hl":false},{"t":"200 g butter","hl":true},{"t":" out to soften (about 1 hour ahead).","hl":false}]},{"text":"Bring the 4 eggs and 200 ml milk to room temperature.","parts":[{"t":"Bring the ","hl":false},{"t":"4 eggs","hl":true},{"t":" and ","hl":false},{"t":"200 ml milk","hl":true},{"t":" to room temperature.","hl":false}]},{"text":"Zest the lemon, then juice it (about 3 tbsp).","parts":[{"t":"Zest the ","hl":false},{"t":"lemon","hl":true},{"t":", then juice it (about 3 tbsp).","hl":false}]},{"text":"Measure 300 g flour, 250 g sugar, 2 tsp baking powder and ¼ tsp salt.","parts":[{"t":"Measure ","hl":false},{"t":"300 g flour","hl":true},{"t":", ","hl":false},{"t":"250 g sugar","hl":true},{"t":", ","hl":false},{"t":"2 tsp baking powder","hl":true},{"t":" and ","hl":false},{"t":"¼ tsp salt","hl":true},{"t":".","hl":false}]}]},{"section":"Prep the pan and dry mix","duration":300,"tip":"Bundt cakes stick in the ridges. Grease every groove, including the centre tube.","youtubeQuery":"how to grease a bundt pan","instructions":[{"text":"Brush every ridge of the bundt pan with soft butter, then dust with 1 tbsp flour, tap out the excess.","parts":[{"t":"Brush every ridge of the bundt pan with soft butter, then dust with ","hl":false},{"t":"1 tbsp flour","hl":true},{"t":", tap out the excess.","hl":false}]},{"text":"In one bowl, whisk the rest of the 300 g flour with 2 tsp baking powder and ¼ tsp salt.","parts":[{"t":"In one bowl, whisk the rest of the ","hl":false},{"t":"300 g flour","hl":true},{"t":" with ","hl":false},{"t":"2 tsp baking powder","hl":true},{"t":" and ","hl":false},{"t":"¼ tsp salt","hl":true},{"t":".","hl":false}]}]},{"section":"Cream the butter and sugar","duration":300,"tip":"Proper creaming whips air into the butter. That air is a big part of what makes the cake light.","youtubeQuery":"how to cream butter and sugar","instructions":[{"text":"Beat 200 g butter with 250 g sugar and the lemon zest on medium-high for 3 to 4 minutes, until pale and fluffy.","parts":[{"t":"Beat ","hl":false},{"t":"200 g butter","hl":true},{"t":" with ","hl":false},{"t":"250 g sugar","hl":true},{"t":" and the lemon zest on ","hl":false},{"t":"medium-high","hl":true},{"t":" for ","hl":false},{"t":"3 to 4 minutes","hl":true},{"t":", until pale and fluffy.","hl":false}]},{"text":"Add the 4 eggs one at a time, beating 30 seconds after each. Scrape down the bowl.","parts":[{"t":"Add the ","hl":false},{"t":"4 eggs","hl":true},{"t":" one at a time, beating ","hl":false},{"t":"30 seconds","hl":true},{"t":" after each. Scrape down the bowl.","hl":false}]}]},{"section":"Make the batter","duration":180,"tip":"Stop mixing as soon as the flour disappears. Overmixing makes a tough, dense cake.","youtubeQuery":"alternating dry and wet ingredients cake batter","instructions":[{"text":"On low speed, add a third of the flour mix, then half the 200 ml milk mixed with 2 tbsp lemon juice.","parts":[{"t":"On ","hl":false},{"t":"low","hl":true},{"t":" speed, add a third of the flour mix, then half the ","hl":false},{"t":"200 ml milk","hl":true},{"t":" mixed with ","hl":false},{"t":"2 tbsp lemon juice","hl":true},{"t":".","hl":false}]},{"text":"Repeat: flour, the rest of the milk, then the last of the flour. Mix only until no dry streaks remain.","parts":[{"t":"Repeat: flour, the rest of the milk, then the last of the flour. Mix only until no dry streaks remain.","hl":false}]},{"text":"Spoon the batter into the pan, smooth the top and tap the pan on the counter twice to pop air bubbles.","parts":[{"t":"Spoon the batter into the pan, smooth the top and tap the pan on the counter twice to pop air bubbles.","hl":false}]}]},{"section":"Bake","duration":2700,"tip":"Don’t open the oven in the first 30 minutes or the cake can sink.","youtubeQuery":"lemon bundt cake baking test doneness","meanwhile":"While it bakes, wash the mixer bowl and set the cooling rack by the oven.","instructions":[{"text":"Bake 45 to 50 minutes, until golden and a skewer pushed into the thickest part comes out clean.","parts":[{"t":"Bake ","hl":false},{"t":"45 to 50 minutes","hl":true},{"t":", until golden and a skewer pushed into the thickest part comes out clean.","hl":false}]},{"text":"Cool in the pan for 10 minutes, then turn out onto the rack.","parts":[{"t":"Cool in the pan for ","hl":false},{"t":"10 minutes","hl":true},{"t":", then turn out onto the rack.","hl":false}]},{"text":"Drizzle with the last 1 tbsp lemon juice while warm. Cool fully (about 1 hour) before slicing into 8 pieces.","parts":[{"t":"Drizzle with the last ","hl":false},{"t":"1 tbsp lemon juice","hl":true},{"t":" while warm. Cool fully (about ","hl":false},{"t":"1 hour","hl":true},{"t":") before slicing into ","hl":false},{"t":"8 pieces","hl":true},{"t":".","hl":false}]}]}]$steps$::jsonb,'json-cookbook') on conflict (slug) do update set name=excluded.name,image=excluded.image,time_mins=excluded.time_mins,kcal=excluded.kcal,servings=excluded.servings,description=excluded.description,steps=excluded.steps,source=excluded.source;
insert into public.recipe_ingredients (recipe_id,canonical,display,quantity,unit,optional,staple) values
  ((select id from public.recipes where slug = 'bundt-cake'),'flour','Flour',300,'g',false,true),
  ((select id from public.recipes where slug = 'bundt-cake'),'sugar','Sugar',250,'g',false,true),
  ((select id from public.recipes where slug = 'bundt-cake'),'butter','Butter',200,'g',false,false),
  ((select id from public.recipes where slug = 'bundt-cake'),'egg','Egg',4,'unit',false,false),
  ((select id from public.recipes where slug = 'bundt-cake'),'milk','Milk',200,'ml',false,false),
  ((select id from public.recipes where slug = 'bundt-cake'),'lemon','Lemon',1,'unit',false,false);
insert into public.recipes (slug,name,image,time_mins,kcal,servings,description,steps,source) values ('tomato-spinach-pasta','Tomato Spinach Pasta','https://thumb.wikimedia.org/wikipedia/commons/thumb/b/b4/Red_Whole_Wheat_Penne_%283357621684%29.jpg/960px-Red_Whole_Wheat_Penne_%283357621684%29.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail',18,480,2,'Penne tossed with garlicky tomato sauce and wilted spinach.',$steps$[{"section":"Get everything ready","duration":240,"tip":"Set up every station before any heat goes under a pan. Once cooking starts, each step moves quickly.","youtubeQuery":"Tomato Spinach Pasta mise en place","instructions":[{"text":"Core 3 tomatoes and chop them into ½ inch (1 cm) pieces.","parts":[{"t":"Core ","hl":false},{"t":"3 tomatoes","hl":true},{"t":" and chop them into ½ inch (1 cm) pieces.","hl":false}]},{"text":"Rinse and drain 100 g spinach.","parts":[{"t":"Rinse and drain ","hl":false},{"t":"100 g spinach","hl":true},{"t":".","hl":false}]},{"text":"Thinly slice 2 cloves garlic and finely grate 30 g parmesan.","parts":[{"t":"Thinly slice ","hl":false},{"t":"2 cloves garlic","hl":true},{"t":" and finely grate ","hl":false},{"t":"30 g parmesan","hl":true},{"t":".","hl":false}]},{"text":"Set the heatproof mug by the stove for pasta water.","parts":[{"t":"Set the heatproof mug by the stove for pasta water.","hl":false}]}]},{"section":"Cook the penne","duration":660,"tip":"Start the sauce once the penne goes in. It takes about the same time.","youtubeQuery":"how to cook penne pasta","meanwhile":"While the penne boils, start the tomato sauce (step 2). It takes about the same time.","instructions":[{"text":"Bring 3 quarts (3 L) water with 1 tbsp salt to a rolling boil.","parts":[{"t":"Bring ","hl":false},{"t":"3 quarts (3 L) water","hl":true},{"t":" with ","hl":false},{"t":"1 tbsp salt","hl":true},{"t":" to a rolling boil.","hl":false}]},{"text":"Add 7 oz (200 g) penne and boil for the packet time minus 1 minute (usually 10 minutes), stirring now and then.","parts":[{"t":"Add ","hl":false},{"t":"7 oz (200 g) penne","hl":true},{"t":" and boil for the packet time minus ","hl":false},{"t":"1 minute","hl":true},{"t":" (usually ","hl":false},{"t":"10 minutes","hl":true},{"t":"), stirring now and then.","hl":false}]},{"text":"Scoop out ½ cup (120 ml) pasta water, then drain.","parts":[{"t":"Scoop out ","hl":false},{"t":"½ cup (120 ml) pasta water","hl":true},{"t":", then drain.","hl":false}]}]},{"section":"Make the tomato sauce","duration":420,"tip":"Pressing the tomatoes as they soften helps them break down faster.","youtubeQuery":"quick fresh tomato sauce","instructions":[{"text":"Warm 2 tbsp olive oil in the skillet over medium heat. Add the sliced 2 cloves garlic and cook 1 minute until fragrant, not brown.","parts":[{"t":"Warm ","hl":false},{"t":"2 tbsp olive oil","hl":true},{"t":" in the skillet over ","hl":false},{"t":"medium","hl":true},{"t":" heat. Add the sliced ","hl":false},{"t":"2 cloves garlic","hl":true},{"t":" and cook ","hl":false},{"t":"1 minute","hl":true},{"t":" until fragrant, not brown.","hl":false}]},{"text":"Add the chopped 3 tomatoes and a pinch of salt. Cook 5 to 6 minutes, pressing with the spoon, until they collapse into a chunky sauce.","parts":[{"t":"Add the chopped ","hl":false},{"t":"3 tomatoes","hl":true},{"t":" and a pinch of salt. Cook ","hl":false},{"t":"5 to 6 minutes","hl":true},{"t":", pressing with the spoon, until they collapse into a chunky sauce.","hl":false}]}]},{"section":"Wilt the spinach and combine","duration":180,"tip":"The spinach looks like a lot but shrinks to almost nothing. Add it gradually so it wilts evenly.","youtubeQuery":"pasta with tomato and spinach","instructions":[{"text":"Add the 100 g spinach a handful at a time, stirring until each batch wilts (about 1 minute total).","parts":[{"t":"Add the ","hl":false},{"t":"100 g spinach","hl":true},{"t":" a handful at a time, stirring until each batch wilts (about ","hl":false},{"t":"1 minute","hl":true},{"t":" total).","hl":false}]},{"text":"Tip in the drained penne and ¼ cup (60 ml) of the pasta water. Toss 1 minute until glossy.","parts":[{"t":"Tip in the drained penne and ","hl":false},{"t":"¼ cup (60 ml)","hl":true},{"t":" of the pasta water. Toss ","hl":false},{"t":"1 minute","hl":true},{"t":" until glossy.","hl":false}]},{"text":"Off the heat, stir in 30 g parmesan. Taste for salt and serve on 2 plates.","parts":[{"t":"Off the heat, stir in ","hl":false},{"t":"30 g parmesan","hl":true},{"t":". Taste for salt and serve on ","hl":false},{"t":"2 plates","hl":true},{"t":".","hl":false}]}]}]$steps$::jsonb,'tandoor') on conflict (slug) do update set name=excluded.name,image=excluded.image,time_mins=excluded.time_mins,kcal=excluded.kcal,servings=excluded.servings,description=excluded.description,steps=excluded.steps,source=excluded.source;
insert into public.recipe_ingredients (recipe_id,canonical,display,quantity,unit,optional,staple) values
  ((select id from public.recipes where slug = 'tomato-spinach-pasta'),'pasta','Penne Pasta',200,'g',false,false),
  ((select id from public.recipes where slug = 'tomato-spinach-pasta'),'tomato','Tomato',3,'unit',false,false),
  ((select id from public.recipes where slug = 'tomato-spinach-pasta'),'spinach','Spinach',100,'g',false,false),
  ((select id from public.recipes where slug = 'tomato-spinach-pasta'),'garlic','Garlic',2,'clove',false,false),
  ((select id from public.recipes where slug = 'tomato-spinach-pasta'),'olive oil','Olive Oil',2,'tbsp',false,true),
  ((select id from public.recipes where slug = 'tomato-spinach-pasta'),'parmesan','Parmesan',30,'g',false,false);
insert into public.recipes (slug,name,image,time_mins,kcal,servings,description,steps,source) values ('veggie-omelette','Veggie Omelette','https://thumb.wikimedia.org/wikipedia/commons/thumb/1/1a/2026-05-10_08_16_25_Omelette_%28with_cheddar%2C_ham%2C_yellow_onions%2C_green_peppers%2C_mushrooms%2C_tomatoes%29%2C_home_fried_potatoes_and_turkey_sausage_patty_at_Capital_Health_Medical_Center_-_Hopewell_in_Hopewell%2C_New_Jersey.jpg/960px-thumbnail.jpg?utm_source=commons.wikimedia.org&utm_campaign=imageinfo&utm_content=thumbnail',8,260,1,'Fluffy eggs folded over sauteed peppers, onion and cheese.',$steps$[{"section":"Get everything ready","duration":180,"tip":"Set up every station before any heat goes under a pan. Once cooking starts, each step moves quickly.","youtubeQuery":"Veggie Omelette mise en place","instructions":[{"text":"Small bowl: crack in 3 eggs, add ½ tsp salt and beat with a fork for 20 to 30 seconds until no streaks of white remain.","parts":[{"t":"Small bowl: crack in ","hl":false},{"t":"3 eggs","hl":true},{"t":", add ","hl":false},{"t":"½ tsp salt","hl":true},{"t":" and beat with a fork for 20 to 30 seconds until no streaks of white remain.","hl":false}]},{"text":"Dice ½ bell pepper into ¼ inch (5 mm) pieces and finely dice ¼ onion.","parts":[{"t":"Dice ","hl":false},{"t":"½ bell pepper","hl":true},{"t":" into ¼ inch (5 mm) pieces and finely dice ","hl":false},{"t":"¼ onion","hl":true},{"t":".","hl":false}]},{"text":"Grate 30 g cheese and measure 1 tbsp butter.","parts":[{"t":"Grate ","hl":false},{"t":"30 g cheese","hl":true},{"t":" and measure ","hl":false},{"t":"1 tbsp butter","hl":true},{"t":".","hl":false}]}]},{"section":"Soften the vegetables","duration":180,"tip":"Softening the veg first means it isn’t crunchy inside a 2 minute omelette.","youtubeQuery":"saute peppers and onions","instructions":[{"text":"Melt ½ tbsp butter in the pan over medium heat until it foams.","parts":[{"t":"Melt ","hl":false},{"t":"½ tbsp butter","hl":true},{"t":" in the pan over ","hl":false},{"t":"medium","hl":true},{"t":" heat until it foams.","hl":false}]},{"text":"Add the diced ½ bell pepper and ¼ onion with a pinch of salt. Cook 2 to 3 minutes, stirring, until soft.","parts":[{"t":"Add the diced ","hl":false},{"t":"½ bell pepper","hl":true},{"t":" and ","hl":false},{"t":"¼ onion","hl":true},{"t":" with a pinch of salt. Cook ","hl":false},{"t":"2 to 3 minutes","hl":true},{"t":", stirring, until soft.","hl":false}]},{"text":"Spread the vegetables evenly across the pan and add the remaining ½ tbsp butter.","parts":[{"t":"Spread the vegetables evenly across the pan and add the remaining ","hl":false},{"t":"½ tbsp butter","hl":true},{"t":".","hl":false}]}]},{"section":"Cook and fold","duration":150,"tip":"Take it off while the top still looks slightly wet. It finishes cooking on the plate.","youtubeQuery":"how to fold an omelette","instructions":[{"text":"Pour in the eggs. Let them sit 15 seconds, then push the set edges to the centre with the spatula and tilt the pan so raw egg runs underneath.","parts":[{"t":"Pour in the eggs. Let them sit ","hl":false},{"t":"15 seconds","hl":true},{"t":", then push the set edges to the centre with the spatula and tilt the pan so raw egg runs underneath.","hl":false}]},{"text":"Repeat for 1 to 1½ minutes until the top is softly set but still slightly glossy.","parts":[{"t":"Repeat for ","hl":false},{"t":"1 to 1½ minutes","hl":true},{"t":" until the top is softly set but still slightly glossy.","hl":false}]},{"text":"Scatter 30 g cheese over one half. Fold the other half over, cook 30 seconds, and slide onto a plate.","parts":[{"t":"Scatter ","hl":false},{"t":"30 g cheese","hl":true},{"t":" over one half. Fold the other half over, cook ","hl":false},{"t":"30 seconds","hl":true},{"t":", and slide onto a plate.","hl":false}]}]}]$steps$::jsonb,'tandoor') on conflict (slug) do update set name=excluded.name,image=excluded.image,time_mins=excluded.time_mins,kcal=excluded.kcal,servings=excluded.servings,description=excluded.description,steps=excluded.steps,source=excluded.source;
insert into public.recipe_ingredients (recipe_id,canonical,display,quantity,unit,optional,staple) values
  ((select id from public.recipes where slug = 'veggie-omelette'),'egg','Egg',3,'unit',false,false),
  ((select id from public.recipes where slug = 'veggie-omelette'),'bell pepper','Bell Pepper',0.5,'unit',false,false),
  ((select id from public.recipes where slug = 'veggie-omelette'),'onion','Onion',0.25,'unit',false,false),
  ((select id from public.recipes where slug = 'veggie-omelette'),'cheese','Cheese',30,'g',false,false),
  ((select id from public.recipes where slug = 'veggie-omelette'),'butter','Butter',1,'tbsp',false,false),
  ((select id from public.recipes where slug = 'veggie-omelette'),'salt','Salt',1,'tsp',false,true);
insert into public.recipes (slug,name,image,time_mins,kcal,servings,description,steps,source) values ('garlic-butter-salmon','Garlic Butter Salmon','https://images.unsplash.com/photo-1467003909585-2f8a72700288?w=600&q=80',20,410,2,'Pan-seared salmon in a lemony garlic butter.',$steps$[{"section":"Get everything ready","duration":240,"tip":"Set up every station before any heat goes under a pan. Once cooking starts, each step moves quickly.","youtubeQuery":"Garlic Butter Salmon mise en place","instructions":[{"text":"Take the 2 salmon fillets out of the fridge 10 minutes ahead.","parts":[{"t":"Take the ","hl":false},{"t":"2 salmon fillets","hl":true},{"t":" out of the fridge 10 minutes ahead.","hl":false}]},{"text":"Thinly slice 3 cloves garlic and cube 2 tbsp butter.","parts":[{"t":"Thinly slice ","hl":false},{"t":"3 cloves garlic","hl":true},{"t":" and cube ","hl":false},{"t":"2 tbsp butter","hl":true},{"t":".","hl":false}]},{"text":"Cut half the lemon into wedges and keep the other half for juicing.","parts":[{"t":"Cut half the ","hl":false},{"t":"lemon","hl":true},{"t":" into wedges and keep the other half for juicing.","hl":false}]},{"text":"Set out paper towels, a basting spoon and a thin spatula.","parts":[{"t":"Set out paper towels, a basting spoon and a thin spatula.","hl":false}]}]},{"section":"Season the salmon","duration":120,"tip":"A dry surface is the secret to crisp skin. Any moisture steams the fish.","youtubeQuery":"how to prep salmon for pan searing","instructions":[{"text":"Pat the 2 salmon fillets dry on all sides with paper towels.","parts":[{"t":"Pat the ","hl":false},{"t":"2 salmon fillets","hl":true},{"t":" dry on all sides with paper towels.","hl":false}]},{"text":"Season the flesh side with ½ tsp salt and 1 tsp black pepper.","parts":[{"t":"Season the flesh side with ","hl":false},{"t":"½ tsp salt","hl":true},{"t":" and ","hl":false},{"t":"1 tsp black pepper","hl":true},{"t":".","hl":false}]}]},{"section":"Sear skin-side down","duration":330,"tip":"If the fillet sticks when you try to flip, wait 30 seconds. It releases when the skin is crisp.","youtubeQuery":"how to pan sear salmon crispy skin","instructions":[{"text":"Heat 1 tbsp oil in the skillet over medium-high until it shimmers (about 2 minutes).","parts":[{"t":"Heat ","hl":false},{"t":"1 tbsp oil","hl":true},{"t":" in the skillet over ","hl":false},{"t":"medium-high","hl":true},{"t":" until it shimmers (about 2 minutes).","hl":false}]},{"text":"Lay the fillets skin-side down, away from you. Press each one with the spatula for 10 seconds so the skin stays flat.","parts":[{"t":"Lay the fillets skin-side down, away from you. Press each one with the spatula for ","hl":false},{"t":"10 seconds","hl":true},{"t":" so the skin stays flat.","hl":false}]},{"text":"Cook 4 to 5 minutes without moving, until the flesh is opaque about two thirds of the way up the sides.","parts":[{"t":"Cook ","hl":false},{"t":"4 to 5 minutes","hl":true},{"t":" without moving, until the flesh is opaque about two thirds of the way up the sides.","hl":false}]},{"text":"Flip and cook 1 to 2 minutes more, until the centre reads 125 to 130°F (52 to 54°C) for medium.","parts":[{"t":"Flip and cook ","hl":false},{"t":"1 to 2 minutes","hl":true},{"t":" more, until the centre reads ","hl":false},{"t":"125 to 130°F (52 to 54°C)","hl":true},{"t":" for medium.","hl":false}]}]},{"section":"Baste with garlic butter","duration":90,"tip":"Pull the pan off the heat as soon as the garlic turns golden. It burns fast in butter.","youtubeQuery":"butter basting salmon garlic","instructions":[{"text":"Turn the heat to low. Add 2 tbsp butter and the sliced 3 cloves garlic.","parts":[{"t":"Turn the heat to ","hl":false},{"t":"low","hl":true},{"t":". Add ","hl":false},{"t":"2 tbsp butter","hl":true},{"t":" and the sliced ","hl":false},{"t":"3 cloves garlic","hl":true},{"t":".","hl":false}]},{"text":"Tilt the pan and spoon the foaming butter over the salmon for 45 to 60 seconds, until the garlic is light gold.","parts":[{"t":"Tilt the pan and spoon the foaming butter over the salmon for ","hl":false},{"t":"45 to 60 seconds","hl":true},{"t":", until the garlic is light gold.","hl":false}]},{"text":"Squeeze over the juice of ½ lemon and serve with the lemon wedges and pan butter on 2 plates.","parts":[{"t":"Squeeze over the juice of ","hl":false},{"t":"½ lemon","hl":true},{"t":" and serve with the lemon wedges and pan butter on ","hl":false},{"t":"2 plates","hl":true},{"t":".","hl":false}]}]}]$steps$::jsonb,'recipe-dataset') on conflict (slug) do update set name=excluded.name,image=excluded.image,time_mins=excluded.time_mins,kcal=excluded.kcal,servings=excluded.servings,description=excluded.description,steps=excluded.steps,source=excluded.source;
insert into public.recipe_ingredients (recipe_id,canonical,display,quantity,unit,optional,staple) values
  ((select id from public.recipes where slug = 'garlic-butter-salmon'),'salmon','Salmon',2,'unit',false,false),
  ((select id from public.recipes where slug = 'garlic-butter-salmon'),'butter','Butter',2,'tbsp',false,false),
  ((select id from public.recipes where slug = 'garlic-butter-salmon'),'garlic','Garlic',3,'clove',false,false),
  ((select id from public.recipes where slug = 'garlic-butter-salmon'),'lemon','Lemon',1,'unit',false,false),
  ((select id from public.recipes where slug = 'garlic-butter-salmon'),'black pepper','Black Pepper',1,'tsp',false,true);
insert into public.recipes (slug,name,image,time_mins,kcal,servings,description,steps,source) values ('chickpea-curry','Chickpea Curry','https://images.unsplash.com/photo-1585937421612-70a008356fbe?w=600&q=80',25,390,3,'Chickpeas simmered in a spiced tomato and onion gravy.',$steps$[{"section":"Get everything ready","duration":300,"tip":"Set up every station before any heat goes under a pan. Once cooking starts, each step moves quickly.","youtubeQuery":"Chickpea Curry mise en place","instructions":[{"text":"Drain and rinse 2 cans chickpeas.","parts":[{"t":"Drain and rinse ","hl":false},{"t":"2 cans chickpeas","hl":true},{"t":".","hl":false}]},{"text":"Finely dice 1 onion and chop 2 tomatoes into ½ inch (1 cm) pieces.","parts":[{"t":"Finely dice ","hl":false},{"t":"1 onion","hl":true},{"t":" and chop ","hl":false},{"t":"2 tomatoes","hl":true},{"t":" into ½ inch (1 cm) pieces.","hl":false}]},{"text":"Finely grate 2 cloves garlic and 1 tbsp ginger.","parts":[{"t":"Finely grate ","hl":false},{"t":"2 cloves garlic","hl":true},{"t":" and ","hl":false},{"t":"1 tbsp ginger","hl":true},{"t":".","hl":false}]},{"text":"Measure 2 tbsp oil, 1 tsp cumin and 1 cup (240 ml) water.","parts":[{"t":"Measure ","hl":false},{"t":"2 tbsp oil","hl":true},{"t":", ","hl":false},{"t":"1 tsp cumin","hl":true},{"t":" and ","hl":false},{"t":"1 cup (240 ml) water","hl":true},{"t":".","hl":false}]}]},{"section":"Cook the onion","duration":420,"tip":"Properly golden onion is the backbone of the curry’s flavour. Don’t rush it on high heat.","youtubeQuery":"how to caramelize onions for curry","instructions":[{"text":"Heat 2 tbsp oil in the pan over medium heat.","parts":[{"t":"Heat ","hl":false},{"t":"2 tbsp oil","hl":true},{"t":" in the pan over ","hl":false},{"t":"medium","hl":true},{"t":" heat.","hl":false}]},{"text":"Add the diced 1 onion with a pinch of salt. Cook 6 to 7 minutes, stirring every minute, until soft and golden at the edges.","parts":[{"t":"Add the diced ","hl":false},{"t":"1 onion","hl":true},{"t":" with a pinch of salt. Cook ","hl":false},{"t":"6 to 7 minutes","hl":true},{"t":", stirring every minute, until soft and golden at the edges.","hl":false}]}]},{"section":"Add the spices","duration":90,"tip":"Toasting ground spices in oil wakes up their flavour. Keep stirring so they don’t burn.","youtubeQuery":"blooming spices in oil","instructions":[{"text":"Stir in the grated 2 cloves garlic and 1 tbsp ginger. Cook 1 minute.","parts":[{"t":"Stir in the grated ","hl":false},{"t":"2 cloves garlic","hl":true},{"t":" and ","hl":false},{"t":"1 tbsp ginger","hl":true},{"t":". Cook ","hl":false},{"t":"1 minute","hl":true},{"t":".","hl":false}]},{"text":"Add 1 tsp cumin and stir 30 seconds until it smells toasty. Add a splash of water if anything starts to catch.","parts":[{"t":"Add ","hl":false},{"t":"1 tsp cumin","hl":true},{"t":" and stir ","hl":false},{"t":"30 seconds","hl":true},{"t":" until it smells toasty. Add a splash of water if anything starts to catch.","hl":false}]}]},{"section":"Make the sauce","duration":300,"tip":"The oil pooling at the sides is the sign the tomato base is cooked.","youtubeQuery":"curry tomato masala base","instructions":[{"text":"Add the chopped 2 tomatoes and ½ tsp salt.","parts":[{"t":"Add the chopped ","hl":false},{"t":"2 tomatoes","hl":true},{"t":" and ","hl":false},{"t":"½ tsp salt","hl":true},{"t":".","hl":false}]},{"text":"Cook 4 to 5 minutes, mashing with the spoon, until they break down into a thick paste and the oil starts to separate at the edges.","parts":[{"t":"Cook ","hl":false},{"t":"4 to 5 minutes","hl":true},{"t":", mashing with the spoon, until they break down into a thick paste and the oil starts to separate at the edges.","hl":false}]}]},{"section":"Simmer the chickpeas","duration":600,"tip":"Too thick? Add water 2 tbsp at a time. Too thin? Simmer uncovered for 2 more minutes.","youtubeQuery":"easy chickpea curry chana masala","meanwhile":"While it simmers, rinse the prep bowls and set out bowls and spoons.","instructions":[{"text":"Add the 2 cans chickpeas and 1 cup (240 ml) water. Stir and bring to a bubble.","parts":[{"t":"Add the ","hl":false},{"t":"2 cans chickpeas","hl":true},{"t":" and ","hl":false},{"t":"1 cup (240 ml) water","hl":true},{"t":". Stir and bring to a bubble.","hl":false}]},{"text":"Cover and simmer on low for 8 to 10 minutes, stirring halfway.","parts":[{"t":"Cover and simmer on ","hl":false},{"t":"low","hl":true},{"t":" for ","hl":false},{"t":"8 to 10 minutes","hl":true},{"t":", stirring halfway.","hl":false}]},{"text":"Mash about ¼ cup of chickpeas against the side of the pan to thicken the sauce. Taste and add up to ½ tsp salt. Serves 3.","parts":[{"t":"Mash about ","hl":false},{"t":"¼ cup","hl":true},{"t":" of chickpeas against the side of the pan to thicken the sauce. Taste and add up to ","hl":false},{"t":"½ tsp salt","hl":true},{"t":". Serves ","hl":false},{"t":"3","hl":true},{"t":".","hl":false}]}]}]$steps$::jsonb,'tandoor') on conflict (slug) do update set name=excluded.name,image=excluded.image,time_mins=excluded.time_mins,kcal=excluded.kcal,servings=excluded.servings,description=excluded.description,steps=excluded.steps,source=excluded.source;
insert into public.recipe_ingredients (recipe_id,canonical,display,quantity,unit,optional,staple) values
  ((select id from public.recipes where slug = 'chickpea-curry'),'chickpeas','Chickpeas',2,'can',false,false),
  ((select id from public.recipes where slug = 'chickpea-curry'),'tomato','Tomato',2,'unit',false,false),
  ((select id from public.recipes where slug = 'chickpea-curry'),'onion','Onion',1,'unit',false,false),
  ((select id from public.recipes where slug = 'chickpea-curry'),'garlic','Garlic',2,'clove',false,false),
  ((select id from public.recipes where slug = 'chickpea-curry'),'ginger','Ginger',1,'tbsp',false,false),
  ((select id from public.recipes where slug = 'chickpea-curry'),'cumin','Cumin',1,'tsp',false,true),
  ((select id from public.recipes where slug = 'chickpea-curry'),'oil','Oil',2,'tbsp',false,true);
insert into public.recipes (slug,name,image,time_mins,kcal,servings,description,steps,source) values ('banana-pancakes','Banana Pancakes','https://images.unsplash.com/photo-1567620905732-2d1ec7ab7445?w=600&q=80',15,330,2,'Soft pancakes sweetened with ripe mashed banana.',$steps$[{"section":"Get everything ready","duration":180,"tip":"Set up every station before any heat goes under a pan. Once cooking starts, each step moves quickly.","youtubeQuery":"Banana Pancakes mise en place","instructions":[{"text":"Peel 2 very ripe bananas.","parts":[{"t":"Peel ","hl":false},{"t":"2 very ripe bananas","hl":true},{"t":".","hl":false}]},{"text":"Melt ½ tbsp butter for the batter and keep ½ tbsp for the pan.","parts":[{"t":"Melt ","hl":false},{"t":"½ tbsp butter","hl":true},{"t":" for the batter and keep ","hl":false},{"t":"½ tbsp","hl":true},{"t":" for the pan.","hl":false}]},{"text":"Measure 150 g flour, 1 tsp baking powder, a pinch of salt and 150 ml milk.","parts":[{"t":"Measure ","hl":false},{"t":"150 g flour","hl":true},{"t":", ","hl":false},{"t":"1 tsp baking powder","hl":true},{"t":", a pinch of salt and ","hl":false},{"t":"150 ml milk","hl":true},{"t":".","hl":false}]},{"text":"Set out the bowl, fork and whisk, the skillet and a ¼ cup measure.","parts":[{"t":"Set out the bowl, fork and whisk, the skillet and a ¼ cup measure.","hl":false}]}]},{"section":"Make the batter","duration":240,"tip":"Overmixing makes pancakes tough. Stop as soon as the flour disappears.","youtubeQuery":"banana pancake batter","meanwhile":"While the batter rests, heat the pan over medium-low and set a plate by the stove for finished pancakes.","instructions":[{"text":"Mash 2 bananas in the bowl with a fork until almost smooth.","parts":[{"t":"Mash ","hl":false},{"t":"2 bananas","hl":true},{"t":" in the bowl with a fork until almost smooth.","hl":false}]},{"text":"Whisk in 2 eggs, the 150 ml milk and ½ tbsp melted butter.","parts":[{"t":"Whisk in ","hl":false},{"t":"2 eggs","hl":true},{"t":", the ","hl":false},{"t":"150 ml milk","hl":true},{"t":" and ","hl":false},{"t":"½ tbsp melted butter","hl":true},{"t":".","hl":false}]},{"text":"Add 150 g flour, 1 tsp baking powder and a pinch of salt. Fold just until no dry flour shows. Small lumps are fine.","parts":[{"t":"Add ","hl":false},{"t":"150 g flour","hl":true},{"t":", ","hl":false},{"t":"1 tsp baking powder","hl":true},{"t":" and a pinch of salt. Fold just until no dry flour shows. Small lumps are fine.","hl":false}]},{"text":"Rest the batter 5 minutes while the pan heats.","parts":[{"t":"Rest the batter ","hl":false},{"t":"5 minutes","hl":true},{"t":" while the pan heats.","hl":false}]}]},{"section":"Cook the pancakes","duration":480,"tip":"Banana batter browns faster than plain. Keep the heat at medium-low.","youtubeQuery":"how to flip pancakes","instructions":[{"text":"Heat the pan over medium-low and wipe with a little of the remaining ½ tbsp butter.","parts":[{"t":"Heat the pan over ","hl":false},{"t":"medium-low","hl":true},{"t":" and wipe with a little of the remaining ","hl":false},{"t":"½ tbsp butter","hl":true},{"t":".","hl":false}]},{"text":"Pour ¼ cup of batter per pancake, leaving space between them.","parts":[{"t":"Pour ","hl":false},{"t":"¼ cup","hl":true},{"t":" of batter per pancake, leaving space between them.","hl":false}]},{"text":"Cook 2 to 3 minutes until bubbles form and pop on top and the edges look set.","parts":[{"t":"Cook ","hl":false},{"t":"2 to 3 minutes","hl":true},{"t":" until bubbles form and pop on top and the edges look set.","hl":false}]},{"text":"Flip and cook 1 to 2 minutes more until golden. Repeat, buttering the pan between batches. Makes about 8 pancakes.","parts":[{"t":"Flip and cook ","hl":false},{"t":"1 to 2 minutes","hl":true},{"t":" more until golden. Repeat, buttering the pan between batches. Makes about ","hl":false},{"t":"8 pancakes","hl":true},{"t":".","hl":false}]}]}]$steps$::jsonb,'json-cookbook') on conflict (slug) do update set name=excluded.name,image=excluded.image,time_mins=excluded.time_mins,kcal=excluded.kcal,servings=excluded.servings,description=excluded.description,steps=excluded.steps,source=excluded.source;
insert into public.recipe_ingredients (recipe_id,canonical,display,quantity,unit,optional,staple) values
  ((select id from public.recipes where slug = 'banana-pancakes'),'banana','Banana',2,'unit',false,false),
  ((select id from public.recipes where slug = 'banana-pancakes'),'flour','Flour',150,'g',false,true),
  ((select id from public.recipes where slug = 'banana-pancakes'),'egg','Egg',2,'unit',false,false),
  ((select id from public.recipes where slug = 'banana-pancakes'),'milk','Milk',150,'ml',false,false),
  ((select id from public.recipes where slug = 'banana-pancakes'),'butter','Butter',1,'tbsp',false,false);
insert into public.recipes (slug,name,image,time_mins,kcal,servings,description,steps,source) values ('shrimp-fried-rice','Shrimp Fried Rice','https://images.unsplash.com/photo-1603133872878-684f208fb84b?w=600&q=80',18,520,2,'Wok-tossed rice with shrimp, egg and vegetables.',$steps$[{"section":"Get everything ready","duration":360,"tip":"Set up every station before any heat goes under a pan. Once cooking starts, each step moves quickly.","youtubeQuery":"Shrimp Fried Rice mise en place","instructions":[{"text":"Break up 10.5 oz (300 g) cold cooked rice with your hands.","parts":[{"t":"Break up ","hl":false},{"t":"10.5 oz (300 g) cold cooked rice","hl":true},{"t":" with your hands.","hl":false}]},{"text":"Pat the 7 oz (200 g) shrimp dry (peeled and deveined).","parts":[{"t":"Pat the ","hl":false},{"t":"7 oz (200 g) shrimp","hl":true},{"t":" dry (peeled and deveined).","hl":false}]},{"text":"Small bowl: beat 2 eggs with a pinch of salt.","parts":[{"t":"Small bowl: beat ","hl":false},{"t":"2 eggs","hl":true},{"t":" with a pinch of salt.","hl":false}]},{"text":"Dice 1 carrot and ½ onion into ¼ inch (5 mm) pieces.","parts":[{"t":"Dice ","hl":false},{"t":"1 carrot","hl":true},{"t":" and ","hl":false},{"t":"½ onion","hl":true},{"t":" into ¼ inch (5 mm) pieces.","hl":false}]},{"text":"Measure 2 tbsp soy sauce and set out 2 plates for the shrimp and egg.","parts":[{"t":"Measure ","hl":false},{"t":"2 tbsp soy sauce","hl":true},{"t":" and set out 2 plates for the shrimp and egg.","hl":false}]}]},{"section":"Sear the shrimp","duration":180,"tip":"Shrimp curled into a tight O is overcooked. Pull them at a loose C.","youtubeQuery":"how to stir fry shrimp","instructions":[{"text":"Heat 1 tbsp oil in the wok over high until it just starts to smoke.","parts":[{"t":"Heat ","hl":false},{"t":"1 tbsp oil","hl":true},{"t":" in the wok over ","hl":false},{"t":"high","hl":true},{"t":" until it just starts to smoke.","hl":false}]},{"text":"Add the 7 oz (200 g) shrimp in one layer. Cook 1 minute per side until pink and curled into a C shape.","parts":[{"t":"Add the ","hl":false},{"t":"7 oz (200 g) shrimp","hl":true},{"t":" in one layer. Cook ","hl":false},{"t":"1 minute per side","hl":true},{"t":" until pink and curled into a C shape.","hl":false}]},{"text":"Move to a plate.","parts":[{"t":"Move to a plate.","hl":false}]}]},{"section":"Scramble the eggs","duration":60,"tip":"Cook the egg separately so it stays in tender pieces instead of coating the rice.","youtubeQuery":"egg for fried rice","instructions":[{"text":"Pour the beaten 2 eggs into the hot wok.","parts":[{"t":"Pour the beaten ","hl":false},{"t":"2 eggs","hl":true},{"t":" into the hot wok.","hl":false}]},{"text":"Stir for 30 to 45 seconds until just set in soft curds, then add to the shrimp plate.","parts":[{"t":"Stir for ","hl":false},{"t":"30 to 45 seconds","hl":true},{"t":" until just set in soft curds, then add to the shrimp plate.","hl":false}]}]},{"section":"Fry the vegetables and rice","duration":300,"tip":"Fresh warm rice turns mushy. Cold rice fries into separate grains.","youtubeQuery":"wok fried rice technique","instructions":[{"text":"Add 1 tbsp oil, then the diced 1 carrot and ½ onion. Stir-fry 2 minutes on high.","parts":[{"t":"Add ","hl":false},{"t":"1 tbsp oil","hl":true},{"t":", then the diced ","hl":false},{"t":"1 carrot","hl":true},{"t":" and ","hl":false},{"t":"½ onion","hl":true},{"t":". Stir-fry ","hl":false},{"t":"2 minutes","hl":true},{"t":" on ","hl":false},{"t":"high","hl":true},{"t":".","hl":false}]},{"text":"Add the 10.5 oz (300 g) cold rice. Press it flat against the wok, leave 30 seconds, then toss. Repeat for 3 minutes until hot and lightly toasted.","parts":[{"t":"Add the ","hl":false},{"t":"10.5 oz (300 g) cold rice","hl":true},{"t":". Press it flat against the wok, leave ","hl":false},{"t":"30 seconds","hl":true},{"t":", then toss. Repeat for ","hl":false},{"t":"3 minutes","hl":true},{"t":" until hot and lightly toasted.","hl":false}]}]},{"section":"Season and serve","duration":90,"tip":"Pouring soy around the hot rim caramelises it slightly for deeper flavour.","youtubeQuery":"shrimp fried rice","instructions":[{"text":"Drizzle 2 tbsp soy sauce around the edge of the wok so it sizzles, then toss.","parts":[{"t":"Drizzle ","hl":false},{"t":"2 tbsp soy sauce","hl":true},{"t":" around the edge of the wok so it sizzles, then toss.","hl":false}]},{"text":"Return the shrimp and egg and toss 1 minute until hot. Taste, and add up to 1 tsp more soy if needed. Serves 2.","parts":[{"t":"Return the shrimp and egg and toss ","hl":false},{"t":"1 minute","hl":true},{"t":" until hot. Taste, and add up to ","hl":false},{"t":"1 tsp","hl":true},{"t":" more soy if needed. Serves ","hl":false},{"t":"2","hl":true},{"t":".","hl":false}]}]}]$steps$::jsonb,'recipe-dataset') on conflict (slug) do update set name=excluded.name,image=excluded.image,time_mins=excluded.time_mins,kcal=excluded.kcal,servings=excluded.servings,description=excluded.description,steps=excluded.steps,source=excluded.source;
insert into public.recipe_ingredients (recipe_id,canonical,display,quantity,unit,optional,staple) values
  ((select id from public.recipes where slug = 'shrimp-fried-rice'),'rice','Rice',300,'g',false,false),
  ((select id from public.recipes where slug = 'shrimp-fried-rice'),'shrimp','Shrimp',200,'g',false,false),
  ((select id from public.recipes where slug = 'shrimp-fried-rice'),'egg','Egg',2,'unit',false,false),
  ((select id from public.recipes where slug = 'shrimp-fried-rice'),'carrot','Carrot',1,'unit',false,false),
  ((select id from public.recipes where slug = 'shrimp-fried-rice'),'onion','Onion',0.5,'unit',false,false),
  ((select id from public.recipes where slug = 'shrimp-fried-rice'),'soy sauce','Soy Sauce',2,'tbsp',false,true),
  ((select id from public.recipes where slug = 'shrimp-fried-rice'),'oil','Oil',2,'tbsp',false,true);
insert into public.recipes (slug,name,image,time_mins,kcal,servings,description,steps,source) values ('greek-yogurt-berry-bowl','Greek Yogurt Berry Bowl','https://images.unsplash.com/photo-1488477181946-6428a0291777?w=600&q=80',5,220,1,'Creamy yogurt topped with berries and a drizzle of honey.',$steps$[{"section":"Get everything ready","duration":60,"tip":"Set up every station before any heat goes under a pan. Once cooking starts, each step moves quickly.","youtubeQuery":"Greek Yogurt Berry Bowl mise en place","instructions":[{"text":"Rinse and dry 100 g berries, halving any large strawberries.","parts":[{"t":"Rinse and dry ","hl":false},{"t":"100 g berries","hl":true},{"t":", halving any large strawberries.","hl":false}]},{"text":"Set out the serving bowl, 200 g Greek yogurt and 1 tbsp honey.","parts":[{"t":"Set out the serving bowl, ","hl":false},{"t":"200 g Greek yogurt","hl":true},{"t":" and ","hl":false},{"t":"1 tbsp honey","hl":true},{"t":".","hl":false}]}]},{"section":"Assemble the bowl","duration":120,"tip":"Add the honey last so it sits on top instead of sinking in.","youtubeQuery":"greek yogurt berry bowl","instructions":[{"text":"Spoon 7 oz (200 g) Greek yogurt into the bowl and swirl the top with the back of the spoon.","parts":[{"t":"Spoon ","hl":false},{"t":"7 oz (200 g) Greek yogurt","hl":true},{"t":" into the bowl and swirl the top with the back of the spoon.","hl":false}]},{"text":"Scatter 3.5 oz (100 g) berries over the yogurt.","parts":[{"t":"Scatter ","hl":false},{"t":"3.5 oz (100 g) berries","hl":true},{"t":" over the yogurt.","hl":false}]},{"text":"Drizzle 1 tbsp honey over the top and eat straight away.","parts":[{"t":"Drizzle ","hl":false},{"t":"1 tbsp honey","hl":true},{"t":" over the top and eat straight away.","hl":false}]}]}]$steps$::jsonb,'json-cookbook') on conflict (slug) do update set name=excluded.name,image=excluded.image,time_mins=excluded.time_mins,kcal=excluded.kcal,servings=excluded.servings,description=excluded.description,steps=excluded.steps,source=excluded.source;
insert into public.recipe_ingredients (recipe_id,canonical,display,quantity,unit,optional,staple) values
  ((select id from public.recipes where slug = 'greek-yogurt-berry-bowl'),'yogurt','Greek Yogurt',200,'g',false,false),
  ((select id from public.recipes where slug = 'greek-yogurt-berry-bowl'),'berries','Berries',100,'g',false,false),
  ((select id from public.recipes where slug = 'greek-yogurt-berry-bowl'),'honey','Honey',1,'tbsp',false,true);
